import numpy as np

# Parse the grid
grid_str = """4 4 4 4 1 1 1 4 4 1 4 4 4 1 1
4 4 4 4 4 4 4 4 4 4 4 1 4 4 4
4 4 4 1 1 4 1 4 4 4 1 4 4 4 1
4 4 4 4 4 4 4 1 4 4 4 4 4 1 1
4 4 4 4 4 4 1 4 1 1 1 4 4 4 4
4 4 4 1 4 4 1 4 4 1 1 4 1 4 4
4 4 1 1 1 1 4 1 1 4 1 4 1 1 1
4 4 1 1 1 1 4 4 1 1 4 1 4 4 4
1 4 4 1 1 4 1 1 1 4 4 4 1 4 4
4 4 1 1 4 4 4 4 1 4 4 4 1 4 4
4 4 4 4 4 4 1 1 4 1 4 4 4 4 1
1 4 4 4 1 4 1 1 4 4 1 4 4 4 4
4 4 4 4 4 1 4 4 1 4 4 1 1 4 4
1 1 1 4 4 4 4 4 1 4 4 1 4 1 4
4 4 1 4 4 4 4 4 4 1 1 4 4 4 1"""

grid = np.array([list(map(int, line.split())) for line in grid_str.strip().split('\n')])

# For each 1-cell, count its 8-neighbor 1s
h, w = 15, 15
degree_counts = {}

for i in range(h):
    for j in range(w):
        if grid[i,j] == 1:
            # Count 8 neighbors
            neighbors = 0
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < h and 0 <= nj < w and grid[ni, nj] == 1:
                        neighbors += 1
            degree = neighbors
            degree_counts[degree] = degree_counts.get(degree, 0) + 1

print("8-neighbor degrees of 1-cells:")
for degree in sorted(degree_counts.keys()):
    print(f"  Degree {degree}: {degree_counts[degree]} cells")

# Let me find cells with specific degrees
for i in range(h):
    for j in range(w):
        if grid[i,j] == 1:
            neighbors = 0
            for di in [-1, 0, 1]:
                for dj in [-1, 0, 1]:
                    if di == 0 and dj == 0:
                        continue
                    ni, nj = i + di, j + dj
                    if 0 <= ni < h and 0 <= nj < w and grid[ni, nj] == 1:
                        neighbors += 1
            if neighbors >= 3:  # Junction points
                print(f"Junction: ({i}, {j}) with {neighbors} neighbors")

